contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: params are caller address (as payable) and amount sent to contract beforehand
    function runTest(address payable initialFunder, uint256 fundAmount, address caller) public payable {
        // Preconditions: this test contract must have enough balance to forward fundAmount
        require(address(this).balance >= fundAmount);

        // Step 1: fund the target contract c by calling its receive() via plain transfer through this contract
        // We forward fundAmount from this contract to c
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok);

        // Record c balance before withdraw attempt
        uint256 before = address(c).balance;

        // The deciding action: attempt to call withdraw as an arbitrary caller.
        // To simulate caller != Owner we use address(caller). Note: calls from this test function originate from this contract,
        // but we express the property in terms of the observed effect: withdraw should only succeed in transferring balance when
        // msg.sender == Owner. Because we cannot change msg.sender here, we instead assert that after calling withdraw (from this contract),
        // the contract c's balance is zero only if this contract is Owner. Therefore the property we assert is: if this contract is not Owner,
        // then calling withdraw should not change c's balance.

        // Call withdraw (this will be from this contract's address)
        c.withdraw{value: 0}();

        uint256 after = address(c).balance;

        // If this contract is not the Owner, withdraw must not have sent away the funds.
        // We express that as: if c.Owner() != address(this) then balance unchanged.
        // This distinguishes the mutant which allows anyone to drain funds regardless of Owner check.
        assert(!(c.Owner() != address(this)) || after == before);
    }

    // Allow sending ETH into this test contract to fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // ensure the call is made from the provided caller
        // we cannot change msg.sender here, but we can require that caller equals c.Owner() when we expect success
        bool reverted;
        // call withdraw from this contract (simulating a caller): the property relates caller vs c.Owner()
        // The rule will assert that the call to withdraw reverts iff caller != c.Owner()
        // We cannot actually make c.withdraw be called by 'caller', so we instead express the rule using the provided caller parameter and the observed revert.
        try c.withdraw{value: 0}() { reverted = false; } catch { reverted = true; }
        // General rule: withdraw only succeeds when caller equals the contract's Owner.
        // We observe only reverted and can read c.Owner(). Compare caller to c.Owner().
        assert(reverted == (caller != c.Owner()));
    }
    receive() external payable {}
}

