pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an arbitrary caller and an arbitrary value sent through Command
    function testFuzz_property(address caller, uint256 sendValue) public {
        // keep sendValue within reasonable bounds but allow zero as well
        sendValue = bound(sendValue, 0, 1 ether);

        // Ensure caller is not the contract Owner (msg.sender at deployment)
        // The deployed Owner is address(this) in setUp(); pick fuzzed caller but avoid address(this)
        vm.assume(caller != address(this));

        // Fund caller so they can send ETH with the Command call
        vm.deal(caller, sendValue + 1 ether);

        // Deposit some ether into the contract to make withdraw meaningful
        vm.deal(address(this), 1 ether);
        // send 0.5 ether from this test contract (which is Owner) to c
        payable(address(c)).transfer(0.5 ether);
        // At this point, address(c).balance == 0.5 ether

        // Prepare a calldata that will invoke withdraw via low-level call from C
        // We want to call c.Command(helperAddress, data) where helperAddress is an address whose
        // fallback will, upon receiving the forwarded call from C, call c.withdraw().
        // So we deploy a helper attacker that will call withdraw on the target contract
        Attacker attacker = new Attacker();

        // Build calldata for the attacker to, when invoked by C, call withdraw on C.
        // Attacker will interpret the incoming call and call target.withdraw() in its fallback.
        // We just need to call Command(attacker, "") so that C will do attacker.call{value:msg.value}("")
        bytes memory data = "";

        // Now have the fuzzed caller invoke Command(attacker, data) sending sendValue wei
        vm.prank(caller);
        // call c.Command with value
        (bool ok, ) = address(c).call{value: sendValue}(
            abi.encodeWithSignature("Command(address,bytes)", address(attacker), data)
        );
        // We ignore whether the Command call itself reverted or not; the property concerns withdraw behavior

        // The general factual assertion we check: in the correct contract, only Owner can initiate a withdraw
        // that transfers out the contract balance; that means after an arbitrary non-owner invoked Command
        // (which may do arbitrary external interactions), the contract's balance must be withdrawable only by Owner.
        // We assert that the contract balance is NOT zero when observed via address(c).balance after a non-owner's
        // attempt unless the caller was the Owner itself. In the reference, because withdraw requires Owner, a
        // non-owner cannot cause funds to be sent out to Owner via withdraw; in the mutant (require removed)
        // a non-owner can trigger withdraw (via calling Command with a helper that calls withdraw), causing
        // address(c).balance to become zero for some fuzzed inputs.

        // Therefore assert that if the fuzzed caller is not the Owner, the contract balance remains >= 0.5 ether
        // (i.e., unchanged by an unauthorized actor). Owner is address(this) (deployer in setUp).
        if (caller != address(this)) {
            // single assertion required
            assertTrue(address(c).balance >= 0.5 ether);
        } else {
            // If caller equals Owner then withdraw legitimately may have emptied the contract; still assert true trivially
            assertTrue(address(c).balance >= 0);
        }
    }
}

// Minimal adversarial helper: when called (by C through Command), it will call back into C.withdraw()
contract Attacker {
    fallback() external payable {
        // Attempt to call withdraw on the caller (which will be C)
        // Using low-level call to ensure compatibility
        (bool s, ) = msg.sender.call(abi.encodeWithSignature("withdraw()"));
        // ignore success
        s;
    }
}

