pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: Only the Owner can successfully withdraw the contract's balance.
    // We fuzz a non-owner attacker address and an amount. We deposit funds into c from Owner,
    // then have the attacker call Command(target, data) where target is an attacker-controlled
    // helper that will call c.withdraw() (i.e., cause c to execute withdraw() from a non-Owner context).
    // The correct contract prevents non-Owners from causing the balance to be transferred out;
    // the mutant (which removed require in withdraw) will allow the attacker's helper to invoke
    // withdraw and cause the contract balance to be sent to Owner. We assert that after the
    // attack attempt the contract balance is unchanged (i.e., only Owner can withdraw).
    function testFuzz_property(address attacker, uint256 sendAmount) public {
        // keep attacker as a non-zero address different from Owner (the fuzzer may pick Owner; allow that but it's okay)
        vm.assume(attacker != address(0));

        // Bound sendAmount to a reasonable range to avoid overflow and to ensure we can fund accounts
        uint256 amount = bound(sendAmount, 1, 1 ether);

        // Fund Owner (which is address(this) within setUp? No: Owner set in C constructor is msg.sender, which was this test contract during setUp)
        // Owner is address(this). We will fund the contract c from Owner by sending value using the Owner (this test contract).
        // Ensure the test contract has enough ETH
        vm.deal(address(this), 2 ether);

        // Deposit amount into c from Owner (this contract is the Owner recorded in c)
        (bool okDeposit, ) = address(c).call{value: amount}("");
        require(okDeposit, "deposit failed");

        // Deploy an adversarial helper that when called will invoke c.withdraw() from the helper's context
        AttackerHelper helper = new AttackerHelper(c);

        // Ensure attacker address has some ETH so that we can prank as attacker when calling Command
        vm.deal(attacker, 1 ether);

        // Build calldata for helper to trigger its call to c.withdraw(); uses empty data since helper will call withdraw on any fallback
        bytes memory data = abi.encodeWithSignature("trigger()");

        // Now have the attacker call c.Command(helper, data) sending zero value.
        // This should NOT cause the contract balance to be transferred out in the correct contract,
        // because withdraw requires msg.sender == Owner, and the helper calling withdraw will be a non-Owner.
        vm.prank(attacker);
        // low-level call into c.Command; it will perform helper.call(...)
        try c.Command(address(helper), data) {
            // ignore success/failure of Command itself
        } catch {}

        // Assertion: the contract balance must still equal the deposited amount (Owner only can withdraw)
        // This is true for the correct contract for all inputs; the mutant (removing require) will allow
        // the helper to call withdraw and drain the balance to Owner, violating this assertion for some inputs.
        assertTrue(address(c).balance == amount);
    }
}

// Helper that when invoked via a call will call c.withdraw() from its own context.
contract AttackerHelper {
    C immutable target;
    constructor(C _t) payable { target = _t; }
    // Expose a function that the test will call via Command's adr.call(data)
    function trigger() external payable {
        // Call withdraw on target from this helper's address (non-Owner)
        target.withdraw{value: 0}();
    }
    // Accept ETH so that low-level call with value (if any) won't revert
    receive() external payable {}
}

