pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller (attacker) and the value sent to Command. We also fuzz a boolean that decides
    // whether the callee (target of Command) will be a benign EOA or an adversarial contract that
    // forwards the call to c.withdraw() (simulating an external party that can call back into c).
    function testFuzz_property(address attacker, uint256 value, bool useAttackerAsCallee) public {
        // keep attacker a non-zero address and not the owner (owner is address(this) at deployment of c)
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        // bound value to a reasonable range so vm.deal works and to allow non-zero funds
        value = bound(value, 0, 1 ether);

        // Fund the contract c with some ether so withdraw has something to transfer
        vm.deal(address(c), 1 ether);

        // Deploy an adversarial helper that, when called, will call c.withdraw() from itself.
        // This models a callee address passed to Command that, during its fallback/receive, calls
        // back into c.withdraw(). In the reference contract withdraw() requires msg.sender == Owner,
        // so the helper's attempt (not being Owner) should not transfer funds; in the mutant it will.
        AttackerHelper helper = new AttackerHelper(c);

        // choose callee address for Command: either the helper (adversarial) or the attacker EOA
        address callee = useAttackerAsCallee ? attacker : address(helper);

        // Ensure attacker has funds to send with Command if value > 0
        if (value > 0) vm.deal(attacker, value);

        // Call Command from attacker, sending `value` wei and asking callee to be invoked.
        // The calldata sent to callee is irrelevant for EOAs; for the helper its fallback will trigger
        // and it will call c.withdraw() from its own address.
        vm.prank(attacker);
        // build calldata arbitrary (empty fine)
        bytes memory data = "";
        try c.Command{value: value}(callee, data) {
            // no-op
        } catch {
            // ignore reverts from Command; property concerns post-state
        }

        // Now: after the above, in the correct contract, only Owner (deployer) can withdraw.
        // The helper attempted to call c.withdraw() from itself — since helper != Owner, in correct C
        // this should NOT have reduced address(c).balance. In the mutant (require removed) the helper's
        // withdraw call would have transferred out the balance to Owner, reducing address(c).balance.

        // Single assertion: address(c).balance must still be 1 ether (unchanged) — this holds for the
        // reference for all admissible inputs; the mutant will allow the helper path to reduce it for
        // some inputs (when useAttackerAsCallee == false), and the fuzzer can find such inputs.
        assertTrue(address(c).balance == 1 ether);
    }
}

// Minimal adversarial helper: when called (fallback/receive), it will call c.withdraw() from its own address.
contract AttackerHelper {
    C public c;
    constructor(C _c) payable { c = _c; }
    receive() external payable {
        // attempt to call withdraw on c from this contract
        // ignore failures
        try c.withdraw() {
        } catch {
        }
    }
    fallback() external payable {
        // same behavior for fallback
        try c.withdraw() {
        } catch {
        }
    }
}

