pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - attacker: the external caller who will invoke Command (must be non-owner to test the invariant)
    // - sendTo: the address passed as `adr` into Command; we will deploy a Reverter helper and pass its address
    // - callValue: ETH sent with Command
    function testFuzz_property(address attacker, uint256 callValue) public {
        // Keep attacker as a non-owner (owner is address(this) at setup because new C() sets Owner = msg.sender)
        vm.assume(attacker != address(this));
        // bound callValue to something reasonable but wide (0..1 ether)
        callValue = bound(callValue, 0, 1 ether);

        // Fund the contract with some baseline balance so withdraw would have something to send
        vm.deal(address(this), 2 ether);
        // Send 1 ether into c from owner (address(this)) so c has initial balance
        c.Command{value: 1 ether}(address(this), ""); // harmless call to self

        // Deploy an adversarial helper whose fallback reverts — this ensures low-level calls to it fail
        Reverter rev = new Reverter();

        // Ensure attacker has ETH to send with Command
        vm.deal(attacker, callValue);

        // Attacker invokes Command, directing the call to the Reverter. We fuzz the value sent.
        vm.prank(attacker);
        // construct calldata arbitrary (empty is fine); low-level call from c to rev will revert
        try c.Command(address(rev), "") {
            // call returned (no revert bubbled) -> ok
        } catch {
            // if c.Command reverts, that's okay for admissible inputs; we continue
        }

        // Now try to have attacker call withdraw via Command (i.e., make c call withdraw() indirectly by targeting c)
        // Build calldata for withdraw() selector
        bytes memory withdrawCalldata = abi.encodeWithSignature("withdraw()");

        // Attacker directs Command to the contract itself with calldata = withdraw(), attempting to get c to call its own withdraw
        vm.prank(attacker);
        try c.Command(address(c), withdrawCalldata) {
            // If this succeeds, then c executed withdraw() as if from attacker
            // The invariant is: in the correct contract, withdraw() will revert for non-owner and thus not send balance
            // We will check c's balance below
        } catch {
            // If it reverted, that's also acceptable behavior
        }

        // Final assertion: in the correct contract, only Owner can cause the contract balance to be transferred out —
        // therefore after the above sequence, address(c).balance must be either unchanged (if withdraw was blocked) or reduced
        // only when the caller was the Owner. Because attacker != owner, the reference contract always preserves the balance here.
        // The single assertion reads c via address(c).balance
        assertTrue(address(c).balance == 1 ether);
    }
}

// Adversarial helper that always reverts on fallback/receive to simulate a failing external callee
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

