pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: caller (potential attacker) and an amount to send through Command to an adversarial helper
    function testFuzz_property(address attacker, uint256 sendAmt) public {
        // keep domain wide but sensible: attacker must not be the Owner (deployed c Owner is this contract)
        // Owner is address(this) because c was created in setUp() by this test contract
        vm.assume(attacker != address(this));
        // bound sendAmt to avoid overflow in vm.deal and make it non-zero to exercise payable paths
        sendAmt = bound(sendAmt, 1, 1 ether);

        // Deploy a helper that will, when called via Command, call c.withdraw() as the caller
        // This simulates an external party causing withdraw to be invoked from within Command.
        CallerHelper helper = new CallerHelper(c);

        // Fund the helper with some ether and also fund c so withdraw has something to send
        vm.deal(address(helper), 0.1 ether);
        vm.deal(address(c), 0.1 ether);

        // Make the attacker call c.Command(helper, calldata) with some value forwarded
        bytes memory data = abi.encodeWithSelector(CallerHelper.doCall.selector);

        // attacker must be able to send ETH to c via Command, so give attacker some balance
        vm.deal(attacker, sendAmt + 0.01 ether);

        // perform the Command call as attacker forwarding sendAmt to helper -> helper will invoke c.withdraw()
        vm.prank(attacker);
        // This low-level call may revert in some variants; we catch it to ensure test continues
        bool ok;
        try c.Command{value: sendAmt}(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after this sequence, the correct contract ensures that a non-Owner
        // cannot have caused the contract balance to be moved out — i.e., address(c).balance must still be >= its initial funding (0.1 ether)
        // The mutant that removed the require in withdraw will allow some attacker inputs to cause the balance to decrease.
        assertTrue(address(c).balance >= 0.1 ether);
    }
}

// Helper contract: when invoked by Command, it will call c.withdraw()
contract CallerHelper {
    C public c;
    constructor(C _c) payable {
        c = _c;
    }
    // called by Command: this will try to invoke withdraw on c
    function doCall() external payable {
        // call c.withdraw() as this helper (not Owner)
        c.withdraw{value: 0}();
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract and check the distinguishing property
    // params:
    // - sender: the address that will call withdraw (simulated by passing as a parameter and using Command to make that address call withdraw)
    // - sendToC: amount of wei to fund c before the deciding call
    // We require this contract to have enough balance to fund c when forwarding via Command.
    function run(address sender, uint256 sendToC) public payable {
        // must have enough balance to forward
        require(address(this).balance >= sendToC);

        // fund c by calling its payable receive via Command: we use Command to make c call an empty data to itself
        // Here we simulate an external send by calling Command with address(c) and empty data, forwarding value
        // Only Owner can call Command on original C, so ensure this contract is Owner by construction of tests
        // (the verifier will use a C instance where this contract is Owner)
        c.Command{value: sendToC}(address(c), "");

        // Now attempt the distinguishing action: have 'sender' call withdraw on c.
        // We cannot directly change msg.sender, but we can have c.Command instruct an external address to call withdraw on c
        // by having c call that address with data specifying a call back into c. We'll craft data for the external address to call c.withdraw().
        // Build calldata for withdraw(): its selector is bytes4(keccak256("withdraw()"))
        bytes memory withdrawSelector = abi.encodeWithSelector(bytes4(keccak256("withdraw()")));

        // In the original contract P, only Owner can successfully cause c.withdraw to execute and transfer balance to Owner.
        // The mutant M inverts the require, allowing non-Owner to trigger the transfer to Owner. We cause 'sender' to invoke withdraw
        // by instructing c to call 'sender' with value 0 and calldata equal to withdrawSelector. That makes 'sender' (if it's a contract) receive the call
        // and if it's a thin proxy that forwards the calldata back to c, this simulates the external address calling withdraw.
        // However, we cannot deploy helpers; instead we use a simpler distinguishing observation: attempt to call c.withdraw directly from this contract
        // and assert that only Owner (which must be this contract for P to hold) can succeed. So require that 'sender' equals address(this) to check Owner path,
        // and if different, the call should revert on P but succeed on M. We'll therefore assert that when msg.sender == address(this), withdraw succeeds.

        // Call withdraw directly from this contract (this is the Owner in the intended setup)
        // This changes state of c and must be a top-level statement.
        c.withdraw{value: 0}();

        // After calling withdraw as Owner, the balance of c must be zero (Owner receives all funds).
        // This is the single distinguishing rule: when the caller is Owner, withdraw empties the contract balance.
        assert(address(c).balance == 0);
    }

    // allow the test contract to receive Ether so it can fund c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // emulate calling withdraw from arbitrary address by using low-level call to this test
        // We cannot change msg.sender for c.withdraw here, but the property must be expressed
        // only over the observable revert behavior when caller != c.Owner().
        // So first read Owner from c
        address owner = c.Owner();
        // If the provided caller equals owner then the call is expected to succeed on P,
        // but we must assert a rule that distinguishes mutant: for any caller != owner,
        // withdraw must revert (i.e., non-Owner cannot succeed). We observe this by
        // performing the call from the current msg.sender to c.withdraw and relating
        // the provided 'caller' parameter to the revert flag. Since we cannot change
        // msg.sender of this call, use the following pattern: require the caller param
        // is different from this contract's msg.sender so behavior depends only on param.
        // (This does not affect c; it's only to express the relation in the assert.)
        // Make the actual call from this contract and record revert.
        try c.withdraw{value:0}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: if the external 'caller' is not equal to c.Owner(), then withdraw must revert.
        // This will hold on P (non-Owner callers cause revert) and be violated by M (non-Owner callers succeed).
        assert(!(caller != owner) || reverted);
    }
    receive() external payable {}
}

